using ICSharpCode.Decompiler.TypeSystem;

namespace ILens;

/// <summary>
/// Recognizes types and members Roslyn, Unity, and Burst emit that aren't part of an
/// assembly's intended public surface — closures, anonymous types, iterator
/// state machines, backing fields, source-generator output. Centralized so every tool
/// that takes <c>include_compiler_generated</c> agrees on what counts as noise.
/// </summary>
public static class CompilerGeneratedFilter
{
    /// <summary>
    /// Is this type compiler-generated by the recognized patterns? Walks the
    /// nesting chain — a nested type inside a generated outer is also generated,
    /// catching cases (e.g. ECMA-suffixed inner helpers in
    /// <c>&lt;PrivateImplementationDetails&gt;</c>) where the inner name itself
    /// doesn't match the prefix list.
    /// </summary>
    public static bool IsCompilerGenerated(ITypeDefinition type)
    {
        for (var t = type; t != null; t = t.DeclaringTypeDefinition)
        {
            if (t.HasAttribute(KnownAttribute.CompilerGenerated)) return true;
            if (IsGeneratedName(t.Name)) return true;
        }
        return false;
    }

    /// <summary>
    /// Is the type of this name compiler-generated by the recognized name patterns? For a type
    /// another assembly defines, which this assembly knows by name alone and whose attributes it
    /// does not hold. Walks the nesting chain as <see cref="IsCompilerGenerated(ITypeDefinition)"/>
    /// does.
    /// </summary>
    public static bool IsCompilerGenerated(FullTypeName name)
    {
        if (IsGeneratedName(name.TopLevelTypeName.Name)) return true;
        for (var level = 0; level < name.NestingLevel; level++)
            if (IsGeneratedName(name.GetNestedTypeName(level))) return true;
        return false;
    }

    /// <summary>
    /// Is this member compiler-generated? It is when its name starts with '<', as a backing
    /// field's or a local function's does, when it is the method Burst adds to start one of its
    /// wrappers, <c>Initialize$X_HHHHHHHH$BurstDirectCall</c>, or when its declaring type is
    /// generated. A field also is when it carries <c>[CompilerGenerated]</c>, when it holds the
    /// subscribers of an event of its class (<see cref="EventOf"/>), and when it is the field an
    /// enum keeps its value in (<see cref="IsEnumValueField"/>). The attribute alone does not
    /// make any other member generated: the compiler puts it on every auto-property accessor,
    /// which is real API.
    /// </summary>
    /// <remarks>
    /// The compilers mark the fields they add with the attribute and give most of them names no
    /// source could declare: the subscriber list of a field-like event, which C# names like the
    /// event and VB after it with <c>Event</c> appended, VB's field for an auto-property or a
    /// <c>WithEvents</c> variable, <c>_X</c>, the fields F# adds for records, unions and
    /// closures, such as <c>X@</c>, and the cached lambdas of the C# compiler before Roslyn,
    /// <c>CS$&lt;&gt;9__...</c>. Of the
    /// 15,627 fields with the attribute whose name does not start with '<', in 3,762 assemblies
    /// counted on 2026-10-20 (.NET 10's shared framework, the .NET SDK, a game's libraries and
    /// its mods), each was one a compiler adds; F# marks no field a <c>let</c> declares. That
    /// compiler before Roslyn left an event's subscriber list unmarked, which the lookup of an
    /// event's subscriber list finds by its shape.
    /// </remarks>
    public static bool IsCompilerGenerated(IMember member) =>
        member.Name.StartsWith('<')
        || member.Name.Contains("$BurstDirectCall", StringComparison.Ordinal)
        || (member is IField field && (field.HasAttribute(KnownAttribute.CompilerGenerated)
            || IsEnumValueField(field) || EventOf(field) != null))
        || (member.DeclaringTypeDefinition is { } declaring && IsCompilerGenerated(declaring));

    /// <summary>
    /// Is this the field an enum keeps its value in, its one field that is not static? The
    /// compiler adds it to every enum as <c>value__</c>, and its type is the enum's underlying
    /// type, which the enum's declaration names after its name where it is not <c>int</c>.
    /// </summary>
    /// <remarks>
    /// No source declares the field, and the decompiled code never shows it: ILSpy writes no
    /// field of an enum that is not a constant, and reads the enum's underlying type from this
    /// field's signature. The test asks for the field that holds the value rather than for any
    /// field that is no constant: a static one, which only IL can put into an enum, is no field a
    /// compiler adds, so it stays listed although the decompiled code leaves it out. Each of the
    /// 19,667 enums in 767 assemblies counted on 2026-10-26 (.NET 10's shared frameworks, the
    /// .NET SDK, a game's libraries and its mods) has exactly one such field, named
    /// <c>value__</c>, and none has a static field that is no constant. Who uses the underlying
    /// type is answered with the enum itself (<see cref="TypeUsageScanner.UsedBy"/>).
    /// </remarks>
    public static bool IsEnumValueField(IField field) =>
        !field.IsStatic && field.DeclaringTypeDefinition?.Kind == TypeKind.Enum;

    /// <summary>
    /// The field holding a field-like event's subscriber list, or <c>null</c> when the event
    /// declares its accessors itself and so has no such field.
    /// </summary>
    public static IField BackingFieldOf(IEvent evt) =>
        evt.DeclaringTypeDefinition?.Fields.FirstOrDefault(field => IsBackingFieldOf(field, evt));

    /// <summary>
    /// The event whose subscriber list <paramref name="field"/> holds, or <c>null</c> for any
    /// other field. A field of a constructed type is looked up as its definition.
    /// </summary>
    public static IEvent EventOf(IField field)
    {
        var definition = (IField)field.MemberDefinition;
        return definition.DeclaringTypeDefinition?.Events.FirstOrDefault(evt => IsBackingFieldOf(definition, evt));
    }

    /// <summary>
    /// True if <paramref name="field"/> is the subscriber list a compiler emitted for
    /// <paramref name="evt"/>: of the same declaring type, private, static exactly when the event
    /// is, and typed as the event's delegate, under the event's own name as C# names it, or
    /// under the event's name with <c>Event</c> appended and marked <c>[CompilerGenerated]</c>
    /// as VB names it.
    /// </summary>
    /// <remarks>
    /// Matching the whole shape is what keeps this from claiming an unrelated field. C# cannot
    /// declare a field of an event's name, so the C# shape needs no attribute, and the C#
    /// compiler before Roslyn wrote it without one. VB reserves the name with <c>Event</c>
    /// appended only for an event whose accessors it writes, so beside a custom event a field
    /// of that name may be declared in source, which the attribute tells apart.
    ///
    /// Type identity goes through <c>ReflectionName</c> rather than <c>IType.Equals</c>.
    /// ILens's type system never loads a referenced assembly, since ILSpyX builds it from the
    /// inspected assembly and a minimal core library, so a type from another assembly, unless
    /// it is one of the core types that library provides, comes back as a distinct unknown-type
    /// instance per resolution site, and the field's type and the event's delegate type compare
    /// unequal despite naming the same type. The name is what survives that, and it has to be
    /// <c>ReflectionName</c>: unlike <c>FullName</c> it carries the generic arity, which tells
    /// <c>Task</c> from <c>Task&lt;TResult&gt;</c>.
    /// </remarks>
    public static bool IsBackingFieldOf(IField field, IEvent evt)
    {
        // The names come first: the filter asks this of every unmarked field against each event
        // of its class, and they rule out nearly every pair before a type's name is built.
        var vbShape = field.Name.Length == evt.Name.Length + VbEventSuffix.Length
            && field.Name.StartsWith(evt.Name, StringComparison.Ordinal)
            && field.Name.EndsWith(VbEventSuffix, StringComparison.Ordinal);
        if (field.Name != evt.Name && !vbShape)
            return false;
        var declaringType = evt.DeclaringTypeDefinition;
        return declaringType != null
            && field.Accessibility == Accessibility.Private
            && field.IsStatic == evt.IsStatic
            && field.DeclaringTypeDefinition?.ReflectionName == declaringType.ReflectionName
            && field.Type.ReflectionName == evt.ReturnType.ReflectionName
            && (!vbShape || field.HasAttribute(KnownAttribute.CompilerGenerated));
    }

    /// <summary>What VB appends to an event's name to name the field of its subscribers.</summary>
    private const string VbEventSuffix = "Event";

    /// <summary>
    /// Is this the copy of a method's code Burst keeps under the name <c>X$BurstManaged</c>? Burst
    /// turns a method X it compiles into a call to its wrapper, which runs the compiled code or
    /// falls back to this copy. The copy is not counted as generated: it holds code the developer
    /// wrote, and the other tools report uses inside it under its own name. compare counts it as
    /// part of X.
    /// </summary>
    public static bool IsBurstManagedCopy(IMember member) =>
        member is IMethod && member.Name.EndsWith("$BurstManaged", StringComparison.Ordinal);

    /// <summary>
    /// Is this the wrapper class or delegate Burst writes for a method it compiles, from the
    /// method's signature alone?
    /// </summary>
    public static bool IsBurstWrapper(ITypeDefinition type) =>
        type.Name.Contains("$BurstDirectCall", StringComparison.Ordinal)
        || type.Name.Contains("$PostfixBurstDelegate", StringComparison.Ordinal);

    /// <summary>
    /// Does this name, a type's own or one segment of a type name a caller wrote, follow one of
    /// the patterns the compiler and the recognized source generators name their types by?
    /// </summary>
    public static bool IsGeneratedName(string name)
    {
        if (string.IsNullOrEmpty(name)) return false;
        // Roslyn convention: every synthetic name starts with '<' — anonymous
        // types, closures, display classes, iterator state machines, async
        // state machines, and the assembly-wide <PrivateImplementationDetails>
        // all share this. A real C# identifier can't start with '<', so the
        // single-character check is correct, not just a heuristic.
        if (name[0] == '<') return true;
        if (name.StartsWith("UnitySourceGeneratedAssembly", StringComparison.Ordinal)) return true;
        if (name.StartsWith("__JobReflectionRegistrationOutput", StringComparison.Ordinal)) return true;
        if (name.StartsWith("BurstDirectCallInitializer", StringComparison.Ordinal)) return true;
        // Burst direct-call wrapper nested types — declaring type is a regular
        // user class (any class with a method Burst compiles), so the chain-walk
        // above can't catch them via the outer type; the wrapper's own name
        // carries a '$'-bearing suffix Burst's source generator emits. '$' is
        // not a valid C# identifier character, so the Contains check has no
        // false-positive risk on hand-written code.
        if (name.Contains("$BurstDirectCall", StringComparison.Ordinal)) return true;
        if (name.Contains("$PostfixBurstDelegate", StringComparison.Ordinal)) return true;
        return false;
    }
}
